namespace IndexAdvisor.Gui.Help;

/// <summary>Тексти довідки «?» для параметрів: що робить, навіщо, коли змінювати. Типове значення, межі й перелік значень GUI додає сам зі схеми.</summary>
internal static class HelpTexts
{
	/// <summary>Ключі YAML-конфігурації: шлях через крапку; поля елементів мапи й списку — через [] (llm.providers[].type).</summary>
	public static readonly IReadOnlyDictionary<string, string> Config = new Dictionary<string, string>(StringComparer.Ordinal)
	{
		["version"] = "Версія формату файлу конфігурації; обов'язковий ключ. Інше значення, ніж підтримує модуль, — помилка конфігурації ще до запуску, тож змінювати його не потрібно.",
		["servers"] = "Імена інстансів SQL Server або listener груп доступності (AG), які треба проаналізувати. Кожен сервер аналізується окремим запуском з власним звітом і архівом; для listener програма сама визначає репліки AG і підключається до кожної напряму. З -FromArchive список ігнорується. Перевизначається параметром -Server.",
		["module"] = "Що аналізувати. Indexes — індекси: правила (дублікати, невикористовувані й відсутні індекси, фрагментація) і рекомендації моделі щодо створення, зміни й видалення; Partitioning — партиціонування: детермінований модуль готує чернетки для великих і вже секціонованих таблиць, а модель їх підтверджує чи відхиляє; Both — обидва аналізи в одному запуску, кожен з окремим діалогом з моделлю, тож токенів витрачається більше. Перевизначається параметром -Module.",

		["scope"] = "Які бази, схеми й таблиці потрапляють в аналіз. Порожній include означає «усе», exclude має пріоритет над include; шаблони * і ? без урахування регістру. Системні бази не аналізуються ніколи.",
		["scope.databases"] = "Фільтр баз на кожному сервері: include — лише ці бази, exclude — пропустити ці. Вужча область скорочує час збору й кількість запитів до сервера.",
		["scope.databases.include"] = "Бази для аналізу; порожньо — усі користувацькі бази в стані ONLINE. Шаблони * і ?, наприклад Sales*. Перевизначається параметром -Database.",
		["scope.databases.exclude"] = "Бази, які пропускаються, навіть якщо підходять під include. Якщо база-репозиторій IndexAdvisor лежить на цільовому сервері, додайте її сюди: інакше запис результатів буде відхилено. Перевизначається параметром -ExcludeDatabase.",
		["scope.schemas"] = "Фільтр схем у кожній базі: include — лише ці схеми, exclude — пропустити ці (наприклад, staging).",
		["scope.schemas.include"] = "Схеми для аналізу; порожньо — усі. Шаблони * і ?. Перевизначається параметром -Schema.",
		["scope.schemas.exclude"] = "Схеми, які пропускаються, навіть якщо підходять під include. Шаблони * і ?. Перевизначається параметром -ExcludeSchema.",
		["scope.tables"] = "Фільтр таблиць. Шаблон з крапкою зіставляється з schema.table (dbo.Log*), без крапки — лише з іменем таблиці в будь-якій схемі.",
		["scope.tables.include"] = "Таблиці для аналізу; порожньо — усі в межах вибраних схем. Формат schema.table або ім'я таблиці, шаблони * і ?. Перевизначається параметром -Table.",
		["scope.tables.exclude"] = "Таблиці, які пропускаються, наприклад журнали dbo.Log*. Формат schema.table або ім'я таблиці, шаблони * і ?. Перевизначається параметром -ExcludeTable.",

		["analysisWindow"] = "Період, за який з Query Store беруться топ-запити. Статистика DMV від нього не залежить: вона накопичується від останнього запуску інстансу чи failover.",
		["analysisWindow.days"] = "Тривалість вікна Query Store в днях. Довше вікно охоплює рідкісні звіти й періодичні задачі, але Query Store має зберігати дані за весь цей час: інакше умова видалення AnalysisWindow не виконується, а звіт попереджає про короткий термін зберігання. Перевизначається параметром -AnalysisWindowDays.",
		["analysisWindow.monthStartRule"] = "Правило початку місяця: у перші analysisWindow.monthStartDays днів місяця вікном береться весь попередній місяць разом з його кінцем (або довший період, якщо так задає days). Так у вікно потрапляє навантаження кінця місяця; для рекомендацій на видалення це одна з умов (AnalysisWindow).",
		["analysisWindow.monthStartDays"] = "Скільки перших днів місяця вважаються його початком для правила monthStartRule. Без увімкненого monthStartRule не діє.",

		["connection"] = "Як програма підключається до цільових серверів. До них надсилаються лише SELECT із системних каталогів, DMV і Query Store; кожен запит відкриває й закриває власне підключення без пулу.",
		["connection.authentication"] = "Sql — SQL-логін connection.login з паролем за посиланням connection.passwordRef; Windows — обліковий запис, під яким запущено програму чи завдання (Integrated Security). В обох випадках логін має збігатися з security.standardLogin, інакше підключення буде відхилено.",
		["connection.login"] = "Ім'я SQL-логіна для автентифікації Sql; має збігатися з security.standardLogin. Логін створює скрипт sql/Setup-IndexAdvisorLogin.sql або вкладка «Інструменти» (Install-IaServiceLogin). Для автентифікації Windows не використовується.",
		["connection.passwordRef"] = "Посилання на пароль SQL-логіна, а не сам пароль: secret:Сховище/Секрет або secret:Секрет (SecretManagement) чи env:ЗМІННА (змінна середовища). Відкритий пароль у YAML — помилка конфігурації. Install-IaServiceLogin сам генерує пароль, зберігає його в сховищі й показує готове посилання; для автентифікації Windows не потрібне.",
		["connection.encrypt"] = "Шифрування з'єднання (Encrypt у рядку підключення). Mandatory — TLS обов'язковий, сертифікат сервера перевіряється, якщо не ввімкнено trustServerCertificate; Optional — шифрування не вимагається, і без примусу з боку сервера шифрується лише вхід; Strict — TDS 8.0: TLS ще до обміну TDS і завжди з перевіркою сертифіката, потрібен SQL Server 2022 або новіший.",
		["connection.trustServerCertificate"] = "Не перевіряти сертифікат сервера (TrustServerCertificate). З'єднання шифрується, але не захищене від підміни сервера, тож вмикайте лише для самопідписаних сертифікатів у тестовому середовищі. З encrypt = Strict ігнорується.",
		["connection.applicationName"] = "Application Name у рядку підключення: за ним сеанси IndexAdvisor видно на сервері (program_name у sys.dm_exec_sessions) і їх легко відрізнити в моніторингу. Підключення до репозиторію отримують це саме ім'я з позначкою (repository).",
		["connection.connectTimeoutSeconds"] = "Скільки секунд чекати на встановлення з'єднання (Connect Timeout). Мережеві збої до входу програма ще двічі повторює, тож за повільної мережі чи віддаленої репліки AG збільште значення. Діє й для бази-репозиторію.",
		["connection.commandTimeoutSeconds"] = "Максимальний час виконання одного запиту до цільового сервера; довший запит переривається з помилкою Timeout. Захищає робочий сервер від затяжних запитів до DMV; unsafe.disableTimeouts вимикає цей таймаут.",
		["connection.lockTimeoutMs"] = "SET LOCK_TIMEOUT перед кожним запитом: скільки мілісекунд чекати на блокування, перш ніж запит завершиться помилкою; 0 — не чекати взагалі. Разом з READ UNCOMMITTED і DEADLOCK_PRIORITY LOW змушує IndexAdvisor поступатися робочому навантаженню.",

		["security"] = "Політика облікового запису: програма підключається лише під штатним логіном із правами на читання метаданих.",
		["security.standardLogin"] = "Ім'я штатного логіна, створеного скриптом sql/Setup-IndexAdvisorLogin.sql (SQL-логін або DOMAIN\\user для Windows). Якщо логін підключення (connection.login чи поточний обліковий запис Windows) з ним не збігається, запуск відхиляється з кодом 3, доки не ввімкнено unsafe.allowNonStandardLogin. Регістр не враховується.",

		["limits"] = "Обмеження обсягу й витрат: рядки одного запиту, довжина тексту команди, кількість дозапитів моделі й токенів на один аналіз.",
		["limits.defaultFetch"] = "Скільки рядків повертає дозапит моделі, якщо модель не вказала кількість (fetch). Більше рядків — більший контекст і більше токенів.",
		["limits.maxRows"] = "Жорстка межа рядків одного запиту: більший fetch дозапиту обрізається до неї, а колектор читає великі набори сторінками такого розміру. Менше значення — більше дрібніших запитів до сервера під час збору.",
		["limits.largeResultWarningRows"] = "Поріг, з якого дозапит моделі отримує попередження про великий обсяг контексту й вартість токенів. Запит не блокується — лише попередження.",
		["limits.maxCommandLength"] = "Максимальна довжина тексту SQL-команди в символах; довший запит відхиляється ще до підключення (CommandTooLong). Захищає від надто великих запитів, зокрема вільних запитів моделі.",
		["limits.maxToolRequestsPerAnalysis"] = "Скільки дозапитів даних модель може виконати за один аналіз. Після ліміту решта дозапитів блокується, модель отримує вимогу дати фінальну відповідь, а звіт попереджає про вичерпаний ліміт; 0 — аналіз лише за початковим контекстом.",
		["limits.maxTokensPerAnalysis"] = "Ліміт токенів (вхід + вихід, сумарно за всі виклики моделі) на один аналіз. Кожен дозапит повторно надсилає весь діалог, тож токени ростуть швидко; після перевищення дозапити блокуються, а рекомендації беруться з останньої відповіді моделі.",

		["collector"] = "Що й як збирається з цільових серверів: набори даних і ліміти часу на найдовші кроки збору.",
		["collector.datasets"] = "Набори даних, які збирає колектор. Вимкнений набір прискорює збір, але знижує достовірність: у кожній рекомендації з'являється попередження, а запуск без помилок завершується з кодом 1. Перевизначається параметрами -Dataset (лише перелічені) і -ExcludeDataset.",
		["collector.datasets.indexStructure"] = "Структура таблиць та індексів — основа аналізу. Обов'язковий набір: вимкнути його не можна, false у YAML — помилка конфігурації.",
		["collector.datasets.instanceStartTime"] = "Час запуску інстансу й останнього failover: від нього рахується період, за який накопичено статистику DMV. Обов'язковий набір: вимкнути його не можна, false у YAML — помилка конфігурації.",
		["collector.datasets.usageStats"] = "Seeks, scans, lookups і updates з sys.dm_db_index_usage_stats. Без нього невикористовувані й write-only індекси визначаються лише за Query Store, рекомендації на видалення менш достовірні, а «дорогі» індекси не розпізнаються. Скрипти обслуговування тоді впорядковують індекси за фрагментацією, а не за range scans.",
		["collector.datasets.operationalStats"] = "Блокування, латчі й розщеплення сторінок з sys.dm_db_index_operational_stats. Без нього очікування на індексах не оцінюються: «дорогий» індекс розпізнається лише за співвідношенням записів і читань, а порад щодо FILLFACTOR у скриптах обслуговування немає.",
		["collector.datasets.sizeAndFragmentation"] = "Розміри й кількість рядків (sys.dm_db_partition_stats) і фрагментація (sys.dm_db_index_physical_stats у режимі LIMITED). Без нього неможливі оцінка розміру й часу побудови нових індексів, знахідки фрагментації й кандидати на партиціонування. Час на physical_stats обмежує collector.physicalStatsTimeBudgetSeconds.",
		["collector.datasets.missingIndexes"] = "Пропозиції SQL Server щодо відсутніх індексів (sys.dm_db_missing_index_*), які програма зливає в кандидати на створення. Без нього кандидати беруться лише з планів Query Store.",
		["collector.datasets.queryStore"] = "Топ-запити й плани Query Store: використання індексів у планах, хінти в текстах запитів, профіль навантаження. Без нього рекомендація на видалення ґрунтується лише на DMV за період роботи сервера, а модуль партиціонування не бачить фільтрів за датою. Для AG читається з primary-репліки.",
		["collector.datasets.constraintsAndReplication"] = "PK, UNIQUE, зовнішні ключі, реплікація, хінти в коді й роль репліки AG — структурні умови безпечного видалення. Без нього ці умови вважаються невиконаними, тож жоден скрипт видалення не буде готовим до виконання.",
		["collector.physicalStatsTimeBudgetSeconds"] = "Сумарний час на sys.dm_db_index_physical_stats в одній базі. Індекси обходяться від найбільших; після вичерпання бюджету решта позначається як пропущена, і їхня фрагментація невідома (процедура обслуговування оцінить їх сама). Обмежує навантаження збору на диски робочого сервера.",
		["collector.queryStorePlansTimeBudgetSeconds"] = "Ліміт часу на збір планів Query Store в одній базі. Якщо його вичерпано або крок збору впав, використання індексів у планах невідоме, і умова видалення NotUsedInQueryStore не виконується. Для баз з великим Query Store збільште значення.",
		["collector.queryStoreTopN"] = "Скільки топ-запитів Query Store брати за кожним критерієм: CPU, логічні читання, тривалість, кількість виконань. Більше значення дає моделі ширший профіль навантаження, але збільшує контекст і вартість.",
		["collector.queryStoreMinFreeSpacePercent"] = "Поріг попередження про заповнення Query Store: якщо вільного місця менше, звіт попереджає про можливий перехід у READ_ONLY і втрату даних. На сам збір не впливає.",

		["archive"] = "Локальний ZIP-архів зібраних даних і промптів кожного запуску. З нього можна повторити аналіз іншою моделлю (-FromArchive) або сформувати скрипти обслуговування без нового збору.",
		["archive.enabled"] = "Зберігати ZIP-архів зібраних даних і промптів. Без архіву неможливі повторний аналіз (-FromArchive) і скрипти обслуговування на вкладці «Інструменти». Перевизначається параметром -NoArchive.",
		["archive.path"] = "Каталог архівів; мапа маскування імен лежить поруч з архівом у файлі .map.json. Архіви містять тексти запитів і структуру баз, тож обирайте захищене місце. Відносний шлях рахується від поточної теки запуску (у GUI — від теки файлу конфігурації).",
		["archive.retentionDays"] = "Архіви разом з їхніми .map.json, старші за цей термін, видаляються з archive.path наприкінці кожного запуску. Не робіть термін коротшим, ніж вам можуть знадобитися повторний аналіз чи скрипти обслуговування з архіву.",
		["archive.restrictAcl"] = "Під час створення каталогу архівів обмежити доступ правами NTFS: лише поточний користувач, SYSTEM і Administrators, без успадкування. Права наявного каталогу не змінюються — програма лише попередить, якщо вони успадковані.",

		["logging"] = "Markdown-журнал сесії: кожен виклик SQL з повним текстом, параметрами, тривалістю й результатом, а також виклики моделі.",
		["logging.path"] = "Каталог журналів; на кожну сесію — окремий файл. Секрети маскуються, але тексти запитів та імена об'єктів лишаються, тож обмежте доступ до каталогу. Відносний шлях рахується від поточної теки запуску (у GUI — від теки файлу конфігурації).",

		["output"] = "Куди й у яких форматах записуються результати запуску.",
		["output.path"] = "Каталог результатів: кожен запуск отримує підтеку <час>_<сервер>_<runId>. Вкладка «Результати» читає запуски саме звідси. Перевизначається параметром -OutputPath.",
		["output.formats"] = "Формати результату: Markdown — recommendations.md; Sql — скрипти виконання й відкату; Html — самодостатній report.html; Json — result.json, без якого запуск зникне з вкладки «Результати» після перезапуску програми й не стане джерелом винятків для скриптів обслуговування; Console — короткий підсумок у консолі чи журналі. Перевизначається параметром -Format.",
		["output.htmlTheme"] = "Тема report.html: Auto — як у браузері чи ОС читача, Light і Dark — примусово. Запуск з GUI передає тему самої програми, тож це значення діє для запусків з командного рядка. Перевизначається параметром -HtmlTheme.",

		["repository"] = "Окрема база історії рекомендацій: рекомендації, обґрунтування, скрипти, модель, вартість і вердикти, на яких тримаються правила видалення. Сирі дані DMV і Query Store туди не потрапляють.",
		["repository.enabled"] = "Записувати результати в репозиторій і читати з нього історію вердиктів. Без репозиторію (разовий аналіз) зараховується лише поточний аналіз, тож скрипт видалення стане готовим, тільки якщо для нього достатньо одного аналізу. Перевизначається параметром -NoRepository.",
		["repository.server"] = "Сервер бази-репозиторію. Якщо репозиторій увімкнено, а сервер не задано, запуск завершиться помилкою репозиторію (код 6); для разового аналізу вимкніть репозиторій.",
		["repository.database"] = "Ім'я бази-репозиторію, створеної скриптом sql/Repository/IndexAdvisor.Repository.sql. Програма пише лише в неї; якщо вона водночас є цільовою базою аналізу, запис відхиляється — виключіть її через scope.databases.exclude.",
		["repository.authentication"] = "Windows — підключення до репозиторію під поточним обліковим записом Windows; Sql — SQL-логін repository.login з паролем за посиланням repository.passwordRef. Логін має бути членом ролі db_index_advisor у базі-репозиторії.",
		["repository.login"] = "SQL-логін для репозиторію, якщо repository.authentication = Sql. Для Windows не використовується.",
		["repository.passwordRef"] = "Посилання на пароль логіна репозиторію, а не сам пароль: secret:Сховище/Секрет, secret:Секрет або env:ЗМІННА. Потрібне лише для автентифікації Sql; відкритий пароль у YAML — помилка конфігурації.",
		["repository.encrypt"] = "Шифрування з'єднання з репозиторієм, як у connection.encrypt: Mandatory — TLS з перевіркою сертифіката, Optional — шифрування не вимагається, Strict — TDS 8.0 із завжди перевіреним сертифікатом (SQL Server 2022 або новіший).",
		["repository.trustServerCertificate"] = "Не перевіряти сертифікат сервера репозиторію. Лише для самопідписаних сертифікатів у тестовому середовищі: з'єднання не захищене від підміни сервера.",
		["repository.historyRetentionDays"] = "Запуски, старші за цей термін, видаляються з репозиторію після кожного запуску разом з рекомендаціями й вердиктами. Не скорочуйте термін настільки, щоб він був коротшим за серію аналізів для правил видалення, інакше старі підтвердження зникнуть.",

		["rules"] = "Детерміновані правила без моделі: пороги знахідок rules engine і умови безпечного видалення індексів (розділ 4.4).",
		["rules.drop"] = "Стандартні умови, за яких рекомендація на видалення індексу вважається готовою до виконання. Скрипт видалення з невиконаними умовами записується із закоментованими інструкціями.",
		["rules.drop.requiredConsecutive"] = "Скільки зарахованих аналізів поспіль мають рекомендувати видалення індексу, перш ніж скрипт стане готовим до виконання. Будь-який вердикт «залишити» обнуляє серію; історія береться з репозиторію.",
		["rules.drop.minIntervalDays"] = "Мінімальний інтервал між зарахованими аналізами серії: запуск раніше цього терміну не додає підтвердження. Не дає зібрати серію кількома запусками поспіль за короткий час.",
		["rules.drop.minUptimeDays"] = "Мінімальний період накопичення статистики (від запуску інстансу чи failover, а для індексу — від його останньої перебудови), за якого аналіз зараховується до серії видалення. Коротший період дає попередження у звіті й код повернення 1; для окремих серверів, баз і таблиць його перевизначає rules.observationOverrides.",
		["rules.relaxed"] = "Пом'якшені правила видалення для «дорогих» індексів: індекс помітно навантажує сервер (блокування, латчі або записи значно переважають читання), а читань з нього мало. Знижуються лише кількість аналізів і мінімальний період; структурні умови (PK, UNIQUE, FK, реплікація, хінти, репліки AG) не пом'якшуються.",
		["rules.relaxed.enabled"] = "Застосовувати пом'якшений профіль до «дорогих» індексів. Вимкнено — усі індекси проходять стандартні правила rules.drop, а знахідка ExpensiveIndex лише показується у звіті.",
		["rules.relaxed.requiredConsecutive"] = "Скільки аналізів поспіль потрібно для видалення «дорогого» індексу замість rules.drop.requiredConsecutive. Мінімальний інтервал rules.drop.minIntervalDays діє й тут.",
		["rules.relaxed.minUptimeDays"] = "Мінімальний період накопичення статистики для «дорогого» індексу. Береться менше з цього значення й стандартного (з урахуванням observationOverrides), тож воно може лише скоротити вимогу.",
		["rules.relaxed.minWriteToReadRatio"] = "Співвідношення updates / (seeks + scans + lookups), з якого записи «значно переважають» читання — одна з ознак «дорогого» індексу. Враховується, лише якщо updates не менше rules.writeOnlyMinUpdates.",
		["rules.relaxed.maxReads"] = "Скільки читань (seeks + scans + lookups) щонайбільше може мати індекс, щоб вважатися «дорогим»: з більшою кількістю читань він під пом'якшені правила не потрапляє навіть за великого навантаження. Без статистики використання (usageStats) індекс «дорогим» не вважається.",
		["rules.relaxed.minLockWaitMs"] = "Сума row_lock_wait_in_ms і page_lock_wait_in_ms, з якої очікування на блокуваннях індексу вважаються помітними — ознака «дорогого» індексу. Потрібен набір operationalStats.",
		["rules.relaxed.minLatchWaitMs"] = "Сума page_latch_wait_in_ms і page_io_latch_wait_in_ms, з якої очікування на латчах індексу вважаються помітними — ознака «дорогого» індексу. Потрібен набір operationalStats.",
		["rules.observationOverrides"] = "Окремий мінімальний період спостереження для сервера, бази чи таблиці замість rules.drop.minUptimeDays — наприклад, довший для бази з квартальною звітністю. Якщо підходять кілька записів, перемагає найточніший: сервер, далі сервер і база, сервер і таблиця, сервер, база й таблиця.",
		["rules.observationOverrides[]"] = "Одне перевизначення періоду спостереження: сервер обов'язковий, база й таблиця звужують область дії.",
		["rules.observationOverrides[].server"] = "Сервер, до якого застосовується перевизначення: ім'я інстансу, репліки або групи доступності (AG). Регістр не враховується.",
		["rules.observationOverrides[].database"] = "База на цьому сервері; порожньо — перевизначення діє на весь сервер. Потрібен точний збіг імені, шаблони не підтримуються.",
		["rules.observationOverrides[].table"] = "Таблиця у форматі schema.table або лише ім'я (тоді в будь-якій схемі); порожньо — уся база чи сервер. Квадратні дужки ігноруються, шаблони не підтримуються.",
		["rules.observationOverrides[].minUptimeDays"] = "Мінімальний період накопичення статистики для цієї області замість rules.drop.minUptimeDays.",
		["rules.maxIndexesPerTable"] = "Поріг знахідки TooManyIndexes: таблиця з більшою кількістю активних індексів позначається як перевантажена індексами. Кожен індекс сповільнює записи; знахідка передається моделі разом з іншими.",
		["rules.writeOnlyMinUpdates"] = "Скільки updates має набрати індекс без жодного читання, щоб вважатися write-only (лише оновлюється); з меншою кількістю він позначається як просто невикористовуваний. Той самий мінімум потрібен для ознаки «записи значно переважають читання» в rules.relaxed.",
		["rules.fragmentation"] = "Пороги фрагментації для знахідок rules engine і для параметрів процедури обслуговування (@minFragmentation, @rebuildThreshold, @minPageCount).",
		["rules.fragmentation.minPageCount"] = "Індекси з меншою кількістю сторінок не перевіряються на фрагментацію: для малих індексів дефрагментація не дає помітного ефекту. Передається процедурі обслуговування як @minPageCount.",
		["rules.fragmentation.reorganizePercent"] = "Фрагментація у відсотках, з якої рекомендується REORGANIZE. Передається процедурі обслуговування як @minFragmentation.",
		["rules.fragmentation.rebuildPercent"] = "Фрагментація у відсотках, з якої замість REORGANIZE рекомендується REBUILD. Передається процедурі обслуговування як @rebuildThreshold.",

		["partitioning"] = "Пороги модуля партиціонування (module = Partitioning або Both): які несекціоновані таблиці є кандидатами і які проблеми шукати в уже секціонованих.",
		["partitioning.minSizeGb"] = "Мінімальний розмір несекціонованої таблиці-кандидата в ГБ. Кандидатом стає лише таблиця, що досягає і цього розміру, і partitioning.minRowCount; потрібен набір sizeAndFragmentation.",
		["partitioning.minRowCount"] = "Мінімальна кількість рядків несекціонованої таблиці-кандидата; діє разом з partitioning.minSizeGb — потрібні обидва пороги.",
		["partitioning.minDateFilterShare"] = "Частка навантаження з Query Store (за вартістю запитів), яка має фільтрувати за одним стовпцем дати чи періоду, щоб секціонування за ним мало сенс. Менша частка — знахідка «секціонування не рекомендовано» без чернетки.",
		["partitioning.maxPartitionSkewRatio"] = "Поріг перекосу секціонованої таблиці: якщо найбільша непорожня секція більша за медіану в стільки разів, з'являється знахідка PartitionSkew.",
		["partitioning.minFuturePartitions"] = "Скільки меж на майбутні періоди має бути попереду в секціонованій таблиці; менше — знахідка з пропозицією нових меж. У чернетку нового секціонування стільки ж місяців закладається наперед.",

		["llm"] = "Аналіз моделлю: провайдер, захист даних (маскування, лише локальна модель), дозапити й облік витрат. Модель отримує лише метадані й не має доступу до серверів.",
		["llm.provider"] = "Ім'я провайдера з llm.providers, яким виконується аналіз. Без нього запуск завершується помилкою конфігурації (код 2). Перевизначається параметром -Provider.",
		["llm.model"] = "Модель замість указаної в налаштуваннях основного провайдера (для Azure OpenAI — ім'я розгортання). На провайдера перехресної перевірки не впливає. Перевизначається параметром -Model.",
		["llm.crossCheckProvider"] = "Другий провайдер з llm.providers, який перевіряє критичні рекомендації першого: видалення індексів і рекомендації з високим ризиком. Вердикт (згоден, не згоден, не впевнений) показується у звіті; кожна перевірка — додаткові виклики й вартість. Перевизначається параметром -CrossCheckProvider.",
		["llm.localOnly"] = "Дозволити лише локальну модель: провайдер типу OpenAICompatible з isLocal = true. Будь-який інший провайдер, зокрема для перехресної перевірки, відхиляється ще до збору даних — для політик, що забороняють передавати метадані в хмарні сервіси. Перевизначається параметром -LocalOnly.",
		["llm.maskNames"] = "Замінювати імена серверів, баз, схем, таблиць, колонок та індексів псевдонімами (srv1, db1, tbl1…) перед відправкою в модель; у рекомендаціях імена відновлюються. Мапа псевдонімів зберігається поруч з архівом (.map.json), а без маскування архів містить справжні імена. Літерали в текстах запитів очищуються завжди. Перевизначається параметром -MaskNames.",
		["llm.autoApproveToolRequests"] = "Виконувати дозапити моделі без діалогу підтвердження. Перевірки безпеки (лише SELECT із системних джерел, лише зібрані сервери й бази, ліміти) діють і далі, але запити до серверів ідуть без вашого перегляду. Потрібне для неінтерактивного запуску з дозапитами. Перевизначається параметром -AutoApprove.",
		["llm.budgetLedgerPath"] = "Локальний JSON-файл обліку витрат на виклики моделі; за ним перевіряються денний і місячний бюджети провайдерів, тож для спільного обліку всі запуски мають писати в той самий файл. Пошкоджений файл блокує виклики, якщо бюджети задано; без бюджетів його буде перейменовано з суфіксом .corrupt, і облік почнеться заново. Відносний шлях рахується від поточної теки запуску (у GUI — від теки файлу конфігурації).",
		["llm.providers"] = "Провайдери моделей за іменами: ключ — довільне ім'я (openai, local), яке вказується в llm.provider, llm.crossCheckProvider чи -Provider. Можна описати кілька й перемикатися між ними без зміни решти конфігурації.",
		["llm.providers[]"] = "Налаштування одного провайдера: тип API, модель, посилання на ключ, ліміти токенів, ціни й бюджети.",
		["llm.providers[].type"] = "Тип API. OpenAI — api.openai.com; Anthropic — моделі Claude через Messages API; Cohere — Cohere Chat API v2; AzureOpenAI — розгортання Azure OpenAI (потрібні endpoint ресурсу й ім'я розгортання в model); OpenAICompatible — будь-який сервер з OpenAI-сумісним API, зокрема локальні Ollama, vLLM чи LM Studio (потрібен endpoint).",
		["llm.providers[].endpoint"] = "Адреса API. Порожньо — стандартна адреса для OpenAI, Anthropic і Cohere; для AzureOpenAI — адреса ресурсу, для OpenAICompatible — базова адреса сервера, наприклад http://localhost:11434/v1. Шлях до методу (/chat/completions, /v1/messages) програма додає сама.",
		["llm.providers[].model"] = "Ідентифікатор моделі провайдера; для AzureOpenAI — ім'я розгортання. Для основного провайдера його можна тимчасово замінити через llm.model чи -Model.",
		["llm.providers[].apiKeyRef"] = "Посилання на API-ключ, а не сам ключ: secret:Сховище/Секрет, secret:Секрет або env:ЗМІННА. Обов'язкове для всіх типів, крім OpenAICompatible, де локальному серверу ключ зазвичай не потрібен. Відкритий ключ у YAML — помилка конфігурації; значення ключа не потрапляє в журнали й тексти помилок.",
		["llm.providers[].apiVersion"] = "Версія API: для AzureOpenAI — параметр api-version (від неї залежить, яким полем передається ліміт вихідних токенів), для Anthropic — заголовок anthropic-version. Порожньо — вбудована версія програми; для інших типів не використовується.",
		["llm.providers[].isLocal"] = "Позначка, що модель працює локально. У режимі llm.localOnly дозволено лише провайдера типу OpenAICompatible з цією позначкою; поза цим режимом вона ні на що не впливає. Ставте її лише для серверів у вашій мережі.",
		["llm.providers[].maxTokensPerRequest"] = "Ліміт вихідних токенів однієї відповіді моделі. У моделей з мисленням (Claude Opus 5.5, o-серія OpenAI) мислення входить у цей ліміт, тож задавайте його з запасом: обрізана відповідь дає окрему помилку з поясненням. Ліміт також входить в оцінку вартості запиту під час перевірки бюджету.",
		["llm.providers[].maxContextTokens"] = "Бюджет вхідного контексту, який програма передає моделі: близько 80% — на дані таблиць, решта — на інструкції, схеми інструментів і дозапити. Більші дані програма стискає, віддаючи пріоритет таблицям зі знахідками rules engine і з топ-запитами Query Store; розмір оцінюється з розрахунку 1,8 байта на токен. Не перевищуйте контекстне вікно моделі.",
		["llm.providers[].dailyBudgetUsd"] = "Денний бюджет провайдера в доларах за даними llm.budgetLedgerPath (доба за UTC); 0 — без ліміту. Перед кожним викликом програма додає оцінку його вартості, і якщо бюджет буде перевищено, аналіз зупиняється з кодом 5. Працює, лише якщо задано ціни токенів.",
		["llm.providers[].monthlyBudgetUsd"] = "Місячний бюджет провайдера в доларах (календарний місяць за UTC) за даними llm.budgetLedgerPath; 0 — без ліміту. Перевищення зупиняє аналіз з кодом 5; без цін токенів вартість рахується як нуль, і бюджет не спрацює.",
		["llm.providers[].inputPricePer1MTokensUsd"] = "Ціна 1 млн вхідних токенів у доларах — для вартості у звіті й перевірки бюджетів. Без ціни вартість дорівнює нулю й бюджети не спрацюють; беріть ціну з прайсу провайдера для вашої моделі.",
		["llm.providers[].outputPricePer1MTokensUsd"] = "Ціна 1 млн вихідних токенів у доларах — для вартості у звіті й перевірки бюджетів. Без ціни вихідні токени вважаються безкоштовними.",
		["llm.providers[].promptCaching"] = "Кешування промптів Anthropic: системний промпт і діалог кешуються, тож дозапити читають великий контекст з кешу значно дешевше; перший виклик платить за запис у кеш. Записані й прочитані з кешу токени показуються у звіті. Діє лише для типу Anthropic.",
		["llm.providers[].cacheWritePricePer1MTokensUsd"] = "Ціна запису 1 млн токенів у кеш промптів у доларах; 0 — 1,25 ціни входу. Впливає лише на розрахунок вартості й бюджетів.",
		["llm.providers[].cacheReadPricePer1MTokensUsd"] = "Ціна читання 1 млн токенів з кешу промптів у доларах; 0 — 0,1 ціни входу для Anthropic і 0,5 для інших типів. Задайте точну ціну моделі, щоб вартість у звіті збігалася з рахунком.",
